  pyq:{freq:"1–2 questions most sessions — among the highest-yield Mechanics chapters.",historical:"Consistently top-3 in Mechanics across multi-year institute analyses.",pattern:"Moment of inertia of standard bodies, rolling without slipping, angular momentum conservation.",difficulty:"Moderate–Hard."},
